<script setup lang="ts">
import{computed,ref}from'vue';import{useRouter}from'vue-router';import{state,refreshMine}from'../store';import{api,run}from'../api';import type{Row}from'../types';import Icon from'../components/Icon.vue';import Status from'../components/Status.vue';import RepairTimeline from'../components/RepairTimeline.vue';import{date}from'../utils'
const router=useRouter(),compose=ref(false),selected=ref<Row|null>(null),busy=ref(false),filter=ref('全部工单'),form=ref({title:'',description:'',location:'',priority:'NORMAL',equipmentId:null as number|null})
const filtered=computed(()=>state.mine.repairs.filter(t=>filter.value==='全部工单'||(filter.value==='处理中'?['OPEN','PROCESSING'].includes(t.status):['RESOLVED','CLOSED'].includes(t.status))))
function create(){if(!state.user){router.push({path:'/login',query:{redirect:'/repairs'}});return}form.value={title:'',description:'',location:'',priority:'NORMAL',equipmentId:null};compose.value=true}
async function submit(){if(!form.value.title.trim()||!form.value.description.trim()||!form.value.location.trim())return;busy.value=true;await run(async()=>{await api('/repairs','POST',form.value);await refreshMine();compose.value=false},'报修已提交，我们会尽快处理');busy.value=false}
</script>
<template><div class="page-content"><div class="page-heading"><div><div class="eyebrow">征途器材保障 · 在线维修</div><h1>在线报修<span class="greeting-dot">.</span></h1><p>记录单车与骑行器材问题，查看维修进度和处理记录。</p></div><el-button type="primary" size="large" @click="create"><Icon name="plus" :size="18"/>提交报修</el-button></div><div class="repair-intro panel"><div class="repair-intro-icon"><Icon name="wrench" :size="40"/></div><div><h3>从提交到解决，每一步都清晰可见</h3><p>设备故障、器材问题都可以在这里提交。请描述具体情况和位置，帮助工作人员更快定位问题。</p><div class="repair-steps"><span>提交工单</span><Icon name="arrow" :size="15"/><span>工作人员受理</span><Icon name="arrow" :size="15"/><span>维修处理</span><Icon name="arrow" :size="15"/><span>修复并关闭</span></div></div></div><div v-if="!state.user" class="panel empty-block"><Icon name="clipboard" :size="42"/><h3>登录后，跟踪你的报修进度</h3><p>你的工单记录会在这里妥善保存。</p><el-button type="primary" @click="router.push('/login?redirect=/repairs')">登录俱乐部账号</el-button></div><template v-else><div class="section-heading"><h2>我的维修工单</h2><el-radio-group v-model="filter"><el-radio-button value="全部工单"/><el-radio-button value="处理中"/><el-radio-button value="已完成"/></el-radio-group></div><div class="ticket-list"><button v-for="t in filtered" :key="t.id" class="panel ticket-card" @click="selected=t"><span class="ticket-number">#{{String(t.id).padStart(5,'0')}}</span><div><h3>{{t.title}}</h3><p>{{t.location}} · {{date(t.createdAt,true)}}</p><span class="small muted">最新进度：{{t.updates.at(-1)?.note}}</span></div><Status :value="t.status"/><Icon name="right" :size="18"/></button></div><el-empty v-if="!filtered.length" description="暂无维修工单记录"/></template></div>
<el-dialog v-model="compose" title="提交维修工单" width="min(620px, 94vw)"><el-form label-position="top" @submit.prevent="submit"><el-form-item label="问题标题" required><el-input v-model="form.title" maxlength="120" placeholder="例如：单车后刹回弹异常"/></el-form-item><div class="form-grid"><el-form-item label="报修地点" required><el-input v-model="form.location" maxlength="120" placeholder="器材编号、存放点或故障发生位置"/></el-form-item><el-form-item label="优先级"><el-select v-model="form.priority"><el-option label="普通" value="NORMAL"/><el-option label="紧急" value="HIGH"/><el-option label="低" value="LOW"/></el-select></el-form-item></div><el-form-item label="关联器材（可选）"><el-select v-model="form.equipmentId" clearable filterable placeholder="选择相关器材"><el-option v-for="e in state.equipment" :key="e.id" :label="e.name+' · '+e.assetCode" :value="e.id"/></el-select></el-form-item><el-form-item label="问题描述" required><el-input v-model="form.description" type="textarea" :rows="5" maxlength="2000" show-word-limit placeholder="请描述故障现象、出现时间和已尝试的处理方式…"/></el-form-item></el-form><template #footer><el-button @click="compose=false">取消</el-button><el-button type="primary" :loading="busy" :disabled="!form.title.trim()||!form.description.trim()||!form.location.trim()" @click="submit">提交工单</el-button></template></el-dialog><el-dialog :model-value="!!selected" @update:model-value="(v:boolean)=>{if(!v)selected=null}" title="维修进度" width="min(650px, 94vw)"><RepairTimeline v-if="selected" :ticket="selected"/></el-dialog></template>
